function buildFloorStack(b){const host=$('bFloorStack');if(!host)return;host.textContent='';const floors=Math.max(1,Number(b.floors)||1),shown=Math.min(80,floors),mode=floorTruth(b.floor_count_method),exact=!!b.exact_layout_available;for(let level=shown;level>=1;level--){const f=document.createElement('div');f.className='floor-slice'+(exact?' exact':mode==='derived from height'?' derived':'');f.title='Above-ground floor '+level+(floors>shown?' · stack capped visually at '+shown+' of '+floors:'');host.appendChild(f)}const ground=document.createElement('div');ground.className='floor-ground';ground.textContent='GROUND';host.appendChild(ground);const undergroundFloors=Math.max(0,Number(b.max_underground_floors)||0),undergroundParts=Math.max(0,Number(b.underground_part_count)||0);if(undergroundFloors>0){for(let level=1;level<=Math.min(20,undergroundFloors);level++){const f=document.createElement('div');f.className='floor-slice subgrade';f.title='Source-backed underground floor '+level;host.appendChild(f)}}else if(undergroundParts>0){const e=document.createElement('div');e.className='floor-subsurface-evidence';e.textContent=undergroundParts+' SUBSURFACE PART'+(undergroundParts===1?'':'S')+' · FLOOR COUNT NOT ASSERTED';host.appendChild(e)}setText('bXrayFloors',floors+' FLOORS');setText('bXrayMode',truthLabel(b));setText('bXrayHeight',b.render_height_m?Number(b.render_height_m).toFixed(1)+' m':'—');setText('bXrayParts',fmt(b.building_part_count));setText('bXrayUnderground',undergroundFloors>0?undergroundFloors+' floors':undergroundParts>0?undergroundParts+' parts':'none asserted');setText('bXrayRoof',[b.roof_shape,b.roof_material].filter(Boolean).join(' · ')||'—');setText('bXrayNote',exact?'Exact lawful public-plan match is linked. This section still renders structural evidence only until public-safe plan geometry is explicitly exposed.':mode==='derived from height'?'Above-ground floor count is derived from height and remains labelled derived. Subsurface floors are only drawn when a source states them.':'Above-ground stack follows source-backed vertical evidence. Subsurface floors are only drawn when explicitly known; no room geometry is invented.')}

function clearMapXray(){
 const map=world?.map;if(!map)return;
 const src=map.getSource('bpV5041XrayFloors');if(src?.setData)src.setData({type:'FeatureCollection',features:[]});
 if(xrayRestore){
  try{if(map.getLayer('gta-bp-buildings'))map.setFilter('gta-bp-buildings',xrayRestore.bpFilter??null)}catch(_){}
  try{if(map.getLayer('gta-opportunity-buildings'))map.setFilter('gta-opportunity-buildings',xrayRestore.oppFilter??null)}catch(_){}
  try{if(map.getLayer('gta-exact-building'))map.setFilter('gta-exact-building',xrayRestore.exactFilter??null)}catch(_){}
  try{if(map.getLayer('gta-context-buildings'))map.setPaintProperty('gta-context-buildings','fill-extrusion-opacity',xrayRestore.contextOpacity)}catch(_){}
 }
 xrayRestore=null
}
function floorSlabFeatures(geometry,b={}){
 const floors=Math.max(1,Math.min(80,Number(b.floors)||1)),base=Number(b.base_height_m||0),top=Math.max(base+2.4,Number(b.render_height_m||b.height_m||floors*3.2)),step=(top-base)/floors;
 const mode=floorTruth(b.floor_count_method),truth=mode==='source-backed'?'SOURCE_BACKED':mode.includes('derived')?'HEIGHT_DERIVED':'SHELL_FALLBACK',features=[];
 for(let i=0;i<floors;i++){const z=base+i*step;features.push({type:'Feature',geometry,properties:{floor_index:i+1,slab_base_m:z,slab_top_m:z+Math.min(.22,Math.max(.08,step*.06)),floor_truth:truth}})}
 const underground=Math.max(0,Math.min(20,Number(b.max_underground_floors)||0));
 for(let i=1;i<=underground;i++){const topZ=base-(i-1)*3.2;features.push({type:'Feature',geometry,properties:{floor_index:-i,slab_base_m:topZ-.18,slab_top_m:topZ,floor_truth:'SOURCE_BACKED_UNDERGROUND'}})}
 return features
}
function applyMapXray(geometry,b={}){
 const map=world?.map;if(!map||!geometry)return;
 const buildingId=b.building_id!=null?String(b.building_id):null;
 const data={type:'FeatureCollection',features:floorSlabFeatures(geometry,b)};
 const existing=map.getSource('bpV5041XrayFloors');
 if(existing?.setData&&map.getLayer('bp-v5041-xray-floors')&&window.__BP_XRAY_STATE__?.buildingId===buildingId){
  existing.setData(data);
  window.__BP_XRAY_STATE__={ready:true,features:data.features.length,buildingId,updatedAt:Date.now(),preserved:true};
  return
 }
 clearMapXray();
 xrayRestore={
  bpFilter:map.getLayer('gta-bp-buildings')?map.getFilter('gta-bp-buildings'):null,
  oppFilter:map.getLayer('gta-opportunity-buildings')?map.getFilter('gta-opportunity-buildings'):null,
  exactFilter:map.getLayer('gta-exact-building')?map.getFilter('gta-exact-building'):null,
  contextOpacity:map.getLayer('gta-context-buildings')?map.getPaintProperty('gta-context-buildings','fill-extrusion-opacity'):null
 };
 if(buildingId){
  const exclude=['!=',['to-string',['coalesce',['get','building_id'],'']],buildingId];
  try{if(map.getLayer('gta-bp-buildings'))map.setFilter('gta-bp-buildings',exclude)}catch(_){}
  try{if(map.getLayer('gta-opportunity-buildings'))map.setFilter('gta-opportunity-buildings',exclude)}catch(_){}
  try{if(map.getLayer('gta-exact-building'))map.setFilter('gta-exact-building',exclude)}catch(_){}
 }
 try{if(map.getLayer('gta-context-buildings'))map.setPaintProperty('gta-context-buildings','fill-extrusion-opacity',.10)}catch(_){}
 const install=()=>{
  try{
    let src=map.getSource('bpV5041XrayFloors');
    if(!src){map.addSource('bpV5041XrayFloors',{type:'geojson',data});src=map.getSource('bpV5041XrayFloors')}else src.setData(data);
    if(!map.getLayer('bp-v5041-xray-floors'))map.addLayer({id:'bp-v5041-xray-floors',type:'fill-extrusion',source:'bpV5041XrayFloors',minzoom:13,paint:{
      'fill-extrusion-color':['match',['get','floor_truth'],'SOURCE_BACKED','#65efff','SOURCE_BACKED_UNDERGROUND','#8c9cff','HEIGHT_DERIVED','#ffd166','#8096a1'],
      'fill-extrusion-height':['get','slab_top_m'],'fill-extrusion-base':['get','slab_base_m'],'fill-extrusion-opacity':.90,'fill-extrusion-vertical-gradient':false
    }});
    if(!map.getLayer('bp-v5041-xray-floor-lines'))map.addLayer({id:'bp-v5041-xray-floor-lines',type:'line',source:'bpV5041XrayFloors',minzoom:13,paint:{'line-color':'#e9ffff','line-width':['interpolate',['linear'],['zoom'],13,.5,18,1.5,21,2.2],'line-opacity':.72}});
    window.__BP_XRAY_STATE__={ready:true,features:data.features.length,buildingId,updatedAt:Date.now()}
  }catch(e){
    window.__BP_XRAY_STATE__={ready:false,features:data.features.length,buildingId,error:String(e?.message||e),updatedAt:Date.now()};
    console.warn('xray install',e);
    setTimeout(()=>{if(!map.getLayer('bp-v5041-xray-floors'))install()},250)
  }
 };
 if(map.isStyleLoaded?.())install();else map.once('styledata',install)
}

