function pointInRing(pt,ring){if(!pt||!ring?.length)return false;let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const xi=+ring[i][0],yi=+ring[i][1],xj=+ring[j][0],yj=+ring[j][1],cross=((yi>pt[1])!==(yj>pt[1]))&&(pt[0]<(xj-xi)*(pt[1]-yi)/((yj-yi)||1e-12)+xi);if(cross)inside=!inside}return inside}
