function geometryApproxCenter(geo){const rings=geometryOuterRings(geo),pts=rings.flat();if(!pts.length)return null;let x=0,y=0,n=0;for(const p of pts){if(Number.isFinite(+p[0])&&Number.isFinite(+p[1])){x+=+p[0];y+=+p[1];n++}}return n?[x/n,y/n]:null}
