async function loadAdvancedPropertyIntel(seq){
 if(!selectedPropertyId)return;
 if(!authSession?.access_token){resetAdvancedPropertyIntel();return}
 resetAdvancedPropertyIntel();
 const id=selectedPropertyId;
 const calls=await Promise.allSettled([
  authRpc('bridgepoint_property_heartbeat_v245',{p_property_id:id},7000),
  authRpc('bridgepoint_property_timeline_v857',{p_property_id:id,p_limit:120},9000),
  authRpc('bridgepoint_property_score_explainability_v1959',{p_property_id:id},7000),
  authRpc('bridgepoint_property_imagery_history_v169',{p_property_id:id},7000)
 ]);
 if(seq!==buildingRequestSeq||id!==selectedPropertyId)return;
 if(calls[0].status==='fulfilled')renderHeartbeat(calls[0].value);else setText('pHeartbeatState','RETRY');
 if(calls[1].status==='fulfilled')renderTimeline(calls[1].value);else{$('pTimelineList').innerHTML='<div class="hazard-item"><b>Timeline refresh will retry.</b></div>'}
 if(calls[2].status==='fulfilled')renderScore(calls[2].value);else setText('pScoreExplanation','Score explanation refresh will retry.');
 if(calls[3].status==='fulfilled')renderImagery(calls[3].value);else{$('pImageryHistory').innerHTML='<div class="hazard-item"><b>Imagery history refresh will retry.</b></div>'}
}
