async function publicAddressFallback(q,timeout=7000){
 const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),timeout);
 try{
  const r=await fetch(SUPA+'/functions/v1/bridgepoint-public-address-geocode-v5300',{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({q}),signal:ctl.signal,cache:'no-store'});
  const d=await r.json().catch(()=>({}));
  if(!r.ok)throw new Error(d?.error||('HTTP '+r.status));
  return d;
 }finally{clearTimeout(timer)}
}
$('publicSearchForm').addEventListener('submit',async e=>{
 e.preventDefault();setMapSearchOpen(true);
 const q=$('publicSearchInput').value.trim(),box=$('publicSearchResults');if(q.length<4)return;
 box.hidden=false;box.innerHTML='<button disabled>Searching BridgePoint…</button>';
 let rows=[],linkedError=null,fallbackUsed=false;
 try{const d=await rpc('bridgepoint_public_search_v5000',{p_query:q,p_limit:8},2800);rows=d?.results||[]}catch(err){linkedError=err}
 if(!rows.length){
  box.innerHTML='<button disabled>Checking public U.S. Census address location…</button>';
  try{const d=await publicAddressFallback(q,7000);rows=d?.results||[];fallbackUsed=rows.length>0}catch(err){console.warn('address fallback',err)}
 }
 if(!rows.length){
  box.innerHTML='<button disabled>No address location or linked BridgePoint property match yet.'+(linkedError?' Linked-address lookup will retry on the next search.':'')+'</button>';
  return;
 }
 box.innerHTML='';
 for(const r of rows){
  const b=document.createElement('button');b.type='button';
  const meta=[r.municipality,r.state_code,r.parcel_number].filter(Boolean);
  if(fallbackUsed||String(r.match_reason||'').startsWith('CENSUS_'))meta.push(r.property_resolved?'Census located · BridgePoint property resolved':'Census located · property link resolving');
  b.innerHTML='<b>'+String(r.full_address||r.geocoder_address||'Address').replace(/[<>&]/g,'')+'</b><small>'+meta.join(' · ')+'</small>';
  b.onclick=()=>{box.hidden=true;setMapSearchOpen(false);const lng=+r.longitude,lat=+r.latitude;if(world?.map&&Number.isFinite(lng)&&Number.isFinite(lat)){world.map.easeTo({center:[lng,lat],zoom:17,pitch:62,bearing:-18,duration:700});selectedFeature=null;showBuilding(lng,lat)}};
  box.appendChild(b)
 }
});

