async function weatherEdge(slug,body={}){
 const s=await ensureAuth();if(!s?.access_token)return null;
 const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),9000);
 try{const r=await fetch(SUPA+'/functions/v1/'+slug,{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+s.access_token,'Content-Type':'application/json'},body:JSON.stringify(body),signal:ctrl.signal,cache:'no-store'});const d=await r.json().catch(()=>({}));if(r.status===401&&s.refresh_token){await refreshAuth();return weatherEdge(slug,body)}if(!r.ok||d?.complete===false&&d?.degraded!==true){if(r.status===403||r.status===401)return null;throw new Error(d?.error||('HTTP '+r.status))}return d}finally{clearTimeout(timer)}
}
function weatherRasterBefore(map){for(const id of ['gta-context-building-shadow','gta-context-buildings','gta-place-label'])if(map.getLayer(id))return id;return undefined}
function ensureWeatherRasterPair(prefix){
 const map=world?.map;if(!map)return;const before=weatherRasterBefore(map);
 for(const side of ['A','B']){const sid='bp'+prefix+side,lid='bp-'+prefix.toLowerCase()+'-'+side.toLowerCase();if(!map.getSource(sid))map.addSource(sid,{type:'raster',tiles:['data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs='],tileSize:256,minzoom:0,maxzoom:12});if(!map.getLayer(lid))map.addLayer({id:lid,type:'raster',source:sid,minzoom:0,maxzoom:13,paint:{'raster-opacity':0,'raster-fade-duration':0,'raster-resampling':'linear'}},before)}
}
function radarTileUrl(epoch){
 const base='https://mapservices.weather.noaa.gov/eventdriven/rest/services/radar/radar_base_reflectivity_time/ImageServer/exportImage';
 return base+'?bbox={bbox-epsg-3857}&bboxSR=3857&imageSR=3857&size=256,256&format=png32&transparent=true&time='+encodeURIComponent(String(epoch))+'&f=image';
}
function swapRaster(prefix,url,opacity){
 const map=world?.map;if(!map||mapInteracting||!liveContextVisible||!url)return;
 ensureWeatherRasterPair(prefix);
 const active=prefix==='Radar'?radarActive:cloudActive,next=active==='A'?'B':'A',sid='bp'+prefix+next,lid='bp-'+prefix.toLowerCase()+'-'+next.toLowerCase(),old='bp-'+prefix.toLowerCase()+'-'+active.toLowerCase(),src=map.getSource(sid);
 try{if(typeof src?.setTiles==='function')src.setTiles([url]);else return}catch(e){console.warn(prefix+' tiles',e);return}
 setTimeout(()=>{if(mapInteracting||!liveContextVisible)return;try{map.setPaintProperty(lid,'raster-opacity',opacity);map.setPaintProperty(old,'raster-opacity',0);if(prefix==='Radar')radarActive=next;else cloudActive=next}catch(_){}},BP_MOBILE?360:260)
}
