 const line=measurePoints.length>1?{type:'Feature',properties:{kind:'line'},geometry:{type:'LineString',coordinates:measurePoints}}:null;
 const poly=measurePoints.length>2?{type:'Feature',properties:{kind:'polygon'},geometry:{type:'Polygon',coordinates:[[...measurePoints,measurePoints[0]]]}}:null;
 const pts=measurePoints.map((c,i)=>({type:'Feature',properties:{kind:'point',index:i+1},geometry:{type:'Point',coordinates:c}}));
